export const viAbout3: Record<string, string> = {
	'amrita-institute-of-medical-sciences-kochi':
		"##history\nAmrita Hospital tại Ponekkara (Kochi), trước đây là Amrita Institute of Medical Sciences (AIMS), được thành lập ngày 17 tháng 5 năm 1998 bởi Mata Amritanandamayi Devi (Amma) với tư cách là bệnh viện đa chuyên khoa chuyên sâu và giảng dạy. Bệnh viện nhận FICCI National Healthcare Excellence Award cho bệnh viện tốt nhất cả nước năm 2013 và thêm hai giải thưởng FICCI năm 2016 về an toàn bệnh nhân và đổi mới công nghệ y tế. Bệnh viện được NABH công nhận, phòng xét nghiệm được NABL công nhận.\n##specialities\nBệnh viện có 29 khoa chuyên môn và 17 trung tâm xuất sắc, được hỗ trợ bởi khoảng 670 giảng viên và 4.000 nhân viên hỗ trợ, phục vụ hơn một triệu lượt khám ngoại trú và hơn 70.000 lượt nhập viện mỗi năm. Các dấu mốc bao gồm ca ghép tụy-thận đồng thời đầu tiên tại Kerala (2014), ca ghép hai bàn tay đầu tiên tại Nam Á (2015), và năm 2021, ca ghép cả hai chi trên đầu tiên sử dụng công nghệ bảo quản mô ghép HEMO2life, ca phẫu thuật thứ chín loại này của bệnh viện. Dịch vụ trải dài từ y học truyền máu và tiết niệu đến phẫu thuật sọ-hàm-mặt và da liễu, thẩm mỹ.\n##technology\nBệnh viện có từ khoảng 1.100 đến 1.450 giường tùy theo nguồn tin khác nhau, khiến đây là một trong những bệnh viện lớn nhất miền nam Ấn Độ. Bệnh viện nằm trên khuôn viên rộng lớn tại Ponekkara, Kochi.\n##international\nAmrita có đội ngũ riêng điều phối việc điều trị cho bệnh nhân quốc tế, với hỗ trợ về visa y tế và chỗ ở, ý kiến y tế trước chuyến đi về điều trị và chi phí, cùng phiên dịch viên đa ngôn ngữ.",
	'aster-medcity':
		"##history\nAster Medcity tại Cheranalloor (Kochi) được Aster DM Healthcare thành lập năm 2013 và bắt đầu hoạt động thử nghiệm năm 2014. Bệnh viện nằm trên khuôn viên 40 mẫu Anh bên bờ sông nước Kochi và là một trong những trung tâm chăm sóc cấp bốn lớn nhất Nam Á. Đây là bệnh viện đa chuyên khoa chăm sóc cấp bốn đầu tiên tại Kerala được JCI công nhận, và trong năm đầu tiên, bệnh viện cũng đạt chứng nhận NABH, chứng nhận xuất sắc về điều dưỡng NABH và chứng nhận Green OT.\n##specialities\nAster Medcity là bệnh viện đa chuyên khoa với tám trung tâm xuất sắc, bao gồm thần kinh, khoa học tim mạch, chỉnh hình, ung bướu, tiêu hóa, thận học, tiết niệu, sức khỏe phụ nữ, nhi khoa, sơ sinh và ghép đa tạng. Đội ngũ ghép tạng đa chuyên khoa gồm các bác sĩ gan mật, thận học, bác sĩ phẫu thuật ghép tạng và hồi sức tích cực xử lý ghép thận, gan, tim và ghép kết hợp. Bệnh viện được cho là bệnh viện đầu tiên tại Kerala cung cấp phẫu thuật robot xâm lấn tối thiểu với hệ thống da Vinci, với hơn 5.000 ca phẫu thuật hỗ trợ robot trong ghép tạng, tiết niệu và phụ khoa.\n##technology\nBệnh viện là cơ sở chăm sóc cấp bốn lớn với vài trăm giường; các nguồn tin nêu từ khoảng 670 đến 800. Khuôn viên được thiết kế vì sự thoải mái của bệnh nhân, có chứng nhận xanh.\n##international\nAster Medcity là điểm đến nổi tiếng cho những người đi khám chữa bệnh tại miền nam Ấn Độ. Cheranalloor gần thành phố Kochi và cách sân bay quốc tế Cochin khoảng 25–30 km.",
	'lakeshore-hospital':
		"##history\nVPS Lakeshore Hospital tại Nettoor (Kochi), trên đường vành đai NH-66, là bệnh viện đa siêu chuyên khoa bắt đầu hoạt động như bệnh viện đa chuyên khoa vào tháng 1 năm 2003. Bệnh viện được NABH công nhận và được mô tả là điểm đến hàng đầu cho du lịch y tế. Bệnh viện nhận giải thưởng Bệnh viện Tốt nhất về Du lịch Y tế của Chính quyền Kerala năm 2014, giải Bệnh viện Tốt nhất Kerala từ Worldwide Achievers năm 2016 và giải Bệnh viện Tốt nhất về Dịch vụ Ung bướu từ Times of India năm 2017.\n##specialities\nBệnh viện có hơn 30 khoa lâm sàng, bao gồm ghép đa tạng, tiêu hóa, thay khớp, tim mạch, phẫu thuật tim mạch và thần kinh. Khoa thận học và ghép thận đã thực hiện hơn 1.600 ca ghép, và trung tâm khoa học tim mạch bao gồm ghép tim và ECMO. Các dấu mốc bao gồm ca ghép gan đầu tiên tại Kerala, ca ghép tủy xương nhi khoa đầu tiên, hệ thống thay khớp gối bằng robot đầu tiên của bang và dịch vụ xe cứu thương hàng không, đường thủy và đường bộ đầu tiên tại Kerala, được Limca Book of Records công nhận.\n##technology\nBệnh viện có vài trăm giường, các nguồn tin nêu từ khoảng 470 đến 650, và dẫn đầu về ghép tạng, chăm sóc tim mạch và phẫu thuật xâm lấn tối thiểu.\n##international\nBệnh viện cung cấp dịch vụ tiếp khách 24 giờ, các lựa chọn thanh toán trước cho bệnh nhân quốc tế, ẩm thực tùy chỉnh, nhân viên đa ngôn ngữ và chấp nhận ngoại tệ.",
	'kims-health-kochi':
		"##history\nKIMS Health, Kochi, là bệnh viện tại Kochi thuộc nhóm các cơ sở KIMS có trụ sở tại Thiruvananthapuram, cũng có các bệnh viện tại Trung Đông. Bệnh viện và trung tâm phẫu thuật tọa lạc tại Pathadipalam, Changampuzha Nagar Post, Edappally, nhằm cung cấp dịch vụ chăm sóc sức khỏe đẳng cấp thế giới với chi phí phải chăng. Bệnh viện được NABH và Australian Council on Healthcare Standards International (ACHSI) công nhận.\n##specialities\nBệnh viện là cơ sở đa chuyên khoa 125 giường với khoảng 25 khoa bao trùm các loại bệnh và tình trạng khác nhau. Bệnh viện cung cấp khoa ngoại trú và nội trú, phòng xét nghiệm, nhà thuốc, X-quang, điện tâm đồ và dịch vụ suốt ngày đêm, được hỗ trợ bởi các bác sĩ tư vấn giàu kinh nghiệm, y tá được đào tạo và nhân viên cận lâm sàng.\n##technology\nBệnh viện hiện đại và được trang bị tốt so với quy mô của mình. So với các bệnh viện lớn nhất tại Kochi, đây là cơ sở nhỏ hơn, vì vậy bệnh nhân có nhu cầu rất phức tạp, chẳng hạn ghép đa tạng, có thể được phục vụ tốt hơn ở nơi khác.\n##international\nEdappally là khu vực nhộn nhịp của Kochi gần trung tâm mua sắm Lulu Mall và ga đường sắt Edappally. Vị trí thuận tiện và quy mô vừa phải giúp bệnh viện phù hợp với bệnh nhân cần các thủ thuật tổng quát hoặc theo kế hoạch trong môi trường thoải mái.",
	'apollo-multispeciality-hospitals-kolkata':
		"##history\nApollo Multispeciality Hospitals, trước đây là Apollo Gleneagles, trên đường Canal Circular Road tại Kolkata, được thành lập năm 2003 và là bệnh viện chăm sóc chuyên sâu 700–750 giường. Đây là bệnh viện duy nhất tại đông Ấn Độ được JCI công nhận. Bệnh viện được khảo sát The Week–Hansa Research xếp hạng bệnh viện tư nhân số 1 miền đông và đông bắc Ấn Độ trong 12 năm liên tiếp, và giành giải Bệnh viện Đa chuyên khoa Tốt nhất Miền Đông Ấn Độ tại Global Health and Travel Awards năm 2019.\n##specialities\nBệnh viện có hơn 50 chuyên khoa và 33 trung tâm xuất sắc, bao gồm chăm sóc tim mạch, chăm sóc ung thư, chỉnh hình, tiêu hóa, thần kinh, ghép tạng, phẫu thuật robot và cấp cứu. Bệnh viện đã thực hiện ca ghép tim, gan và thận đồng thời đầu tiên tại đông Ấn Độ và mang đến khu vực kỹ thuật ghép thận hoàn toàn bằng robot; tập đoàn Apollo đã thực hiện hơn 10.000 ca ghép thận. Bệnh viện cũng là cái tên đáng tin cậy cho ca ghép tủy xương của bệnh nhân quốc tế.\n##technology\nBệnh viện xử lý hơn 1.600 lượt khám ngoại trú mỗi ngày và có các trung tâm ghép tạng được trang bị cho phẫu thuật với người hiến sống và người hiến đã qua đời.\n##international\nHơn 10.000 bệnh nhân quốc tế mỗi năm, nhiều người đến từ Bangladesh, được điều trị tại Apollo Kolkata, nơi có đội ngũ riêng phục vụ bệnh nhân quốc tế. Bệnh viện nằm tại khu vực Kankurgachi, Kolkata.",
	'amri-hospitals-dhakuria':
		"##history\nAMRI Hospitals, Dhakuria, bắt đầu năm 1996 với tư cách là dự án hợp tác công tư với Chính quyền West Bengal, lúc đầu là cơ sở ngoại trú, phát triển thành bệnh viện 150 giường năm 1997 và sau đó mở rộng lên vài trăm giường. Manipal Hospitals mua lại phần lớn cổ phần trong tập đoàn AMRI năm 2023, và bệnh viện Dhakuria hiện là Manipal Hospital Dhakuria (trước đây là AMRI), với Manipal hiện diện tại Salt Lake, Dhakuria, Mukundapur và Broadway ở Kolkata. Dưới thương hiệu AMRI, bệnh viện được vinh danh Bệnh viện Tư nhân Tốt nhất Miền Đông Ấn Độ tại ABP News Healthcare Leadership Awards năm 2020 và 2021.\n##specialities\nBệnh viện nổi tiếng về khoa học tim mạch, thay khớp, chăm sóc chấn thương, thụ tinh trong ống nghiệm, phẫu thuật hàm mặt và phẫu thuật thẩm mỹ, tạo hình. Dịch vụ cấp cứu và hồi sức tích cực của bệnh viện là trung tâm xuất sắc. Năm 2024, bệnh viện nhận giải thưởng tại Economic Times Healthcare Awards về đóng góp cho chăm sóc cấp cứu và xuất sắc trong thần kinh học và quản lý đột quỵ, và được Chính phủ Bangladesh ghi nhận vì phục vụ bệnh nhân Bangladesh.\n##technology\nHình ảnh hạt nhân tiên tiến bao gồm PET-CT và SPECT-CT, và xạ trị bao gồm IMRT và VMAT. Bệnh viện được NABH công nhận. Bệnh viện nằm trên đường Gariahat Road, Dhakuria, nam Kolkata.\n##international\nManipal Hospitals cung cấp dịch vụ riêng cho bệnh nhân quốc tế, bao gồm ý kiến y tế, lập kế hoạch điều trị, hỗ trợ du lịch và hỗ trợ cá nhân hóa.",
	'fortis-hospital-anandapur':
		"##history\nFortis Hospital, Anandapur, tại Kolkata được thành lập năm 2011 và trải rộng khoảng bảy mẫu Anh dọc theo Eastern Metropolitan Bypass. Đây là tòa nhà 10 tầng, khoảng 300 giường, với khoảng 240 giường đang hoạt động. Các dấu mốc bao gồm ca thay khớp gối theo đơn đặt hàng đầu tiên tại đông Ấn Độ (2011), ca mở sọ khi tỉnh đầu tiên tại đông Ấn Độ (2012), khởi động Heart Team đầu tiên tại Ấn Độ (2012) và ca ghép thận nhi khoa dưới 12 kg (2014). Bệnh viện nhận danh hiệu Times Bengal Icons 2023 cho cơ sở chăm sóc chấn thương tốt nhất thành phố và các giải thưởng tại CAHOCON 2024.\n##specialities\nBệnh viện chuyên về tim mạch và phẫu thuật tim, tiết niệu, thận học, thần kinh, chỉnh hình, chăm sóc tiêu hóa, hô hấp, chăm sóc mẹ và bé, cấp cứu và hồi sức tích cực. Bệnh viện cũng có các phòng khám chuyên khoa về tăng áp phổi, thở máy không xâm lấn và dị ứng, và cung cấp ung bướu, phẫu thuật hàm mặt, nha khoa, tâm thần, đái tháo đường, da liễu và tai mũi họng. Trung tâm tim mạch có bốn phòng can thiệp qua ống thông, một phòng mổ tim, SICU 14 giường và CCU 20 giường.\n##technology\nBệnh viện có chứng nhận NABH và chứng nhận NABL.\n##international\nLà một phần của Fortis Healthcare, bệnh viện hỗ trợ bệnh nhân quốc tế thông qua các dịch vụ quốc tế của tập đoàn. Bệnh viện nằm tại Anandapur, trên EM Bypass, thuận tiện cho các khu kinh doanh và sân bay.",
	'medica-superspecialty-hospital':
		"##history\nMedica Superspecialty Hospital tại Mukundapur được khởi động năm 2010 và thuộc tập đoàn Medica, được mô tả là chuỗi bệnh viện lớn nhất miền đông Ấn Độ. Đây là bệnh viện chăm sóc chuyên sâu với vài trăm giường, 18 khoa và tám trung tâm xuất sắc, tại 127 Eastern Metropolitan Bypass. Vào tháng 2 năm 2022, bệnh viện lắp đặt robot da Vinci thế hệ thứ tư, trở thành trung tâm đào tạo phẫu thuật robot chính thức đầu tiên tại miền đông Ấn Độ. Đây cũng là bệnh viện đầu tiên tại miền đông Ấn Độ có Phòng mổ Xanh được chứng nhận, và nhận Times Bengal Award năm 2023.\n##specialities\nBệnh viện bao phủ gây mê, tim mạch, phẫu thuật tim, hồi sức tích cực, da liễu, nha khoa, y học cấp cứu, nội tiết, tai mũi họng, tiêu hóa, phẫu thuật tổng quát và tiêu hóa, huyết học, bệnh gan, thận học, thần kinh, phẫu thuật thần kinh, thần kinh học tai, y học hạt nhân, chỉnh hình, sản phụ khoa, ung bướu, phẫu thuật nhi khoa, phẫu thuật thẩm mỹ và tạo hình, phục hồi chức năng, tâm thần, X-quang, hô hấp, thấp khớp, phẫu thuật robot, y học truyền máu và tiết niệu.\n##technology\nMedica có một trong những đơn vị hồi sức tích cực tiên tiến nhất khu vực, phòng xét nghiệm được NABL công nhận với phòng thí nghiệm phân tử và dịch vụ hình ảnh đạt tiêu chuẩn quốc tế. Trung tâm lọc máu của bệnh viện được công nhận năm 2020 và giành giải thưởng nhà cung cấp dịch vụ lọc máu tốt nhất. Bệnh viện được NABH và NABL công nhận.\n##international\nMedica cung cấp dịch vụ cho bệnh nhân quốc tế và là điểm đến nổi tiếng cho bệnh nhân từ các nước láng giềng.",
	'zydus-hospitals':
		"##history\nZydus Hospitals tại Ahmedabad là sáng kiến của Zydus Group, khai trương năm 2015 trên S. G. Highway gần Sola Bridge. Đây là bệnh viện siêu chuyên khoa 550 giường trên 16 tầng và hai tầng hầm, được NABH và NABL công nhận. Bệnh viện được khảo sát The Week–Marg công nhận là Bệnh viện Tốt nhất Ahmedabad trong bốn năm và là bệnh viện thứ 18 tại Gujarat giành giải Global Green-OT. Bệnh viện đã bổ nhiệm các chuyên gia y tế được đào tạo tại Hoa Kỳ và châu Âu.\n##specialities\nZydus là trung tâm về thần kinh, chăm sóc tiêu hóa, tiết niệu, phụ khoa, ung bướu, cột sống, phẫu thuật thẩm mỹ và tạo hình, thận học và tai mũi họng, với các trung tâm xuất sắc về thụ tinh trong ống nghiệm, thay khớp, chăm sóc ung thư, thần kinh, phẫu thuật tim, ghép thận, ghép gan, phẫu thuật thần kinh và phẫu thuật tạo hình. Chương trình ghép gan được hỗ trợ bởi đội ngũ đa chuyên khoa hơn 20 chuyên gia, và tại các trung tâm ở Ahmedabad và Vadodara, bệnh viện đã thực hiện hơn 430 ca ghép thận, hơn 295 ca ghép gan và hơn 220 ca ghép tủy xương.\n##technology\nBệnh viện kết hợp phòng mổ hiện đại, hình ảnh tiên tiến và năng lực hồi sức tích cực lớn với các thực hành xây dựng xanh.\n##international\nAhmedabad đã nổi lên như một điểm đến quan trọng tại miền tây Ấn Độ, và Zydus thu hút số lượng bệnh nhân quốc tế ngày càng tăng; các bác sĩ của bệnh viện cũng tổ chức các trại y tế tại các nước châu Phi và Uzbekistan.",
	'cims-hospital':
		"##history\nCIMS Hospital, nay là Marengo Asia CIMS Hospital, khai trương năm 2010 gần đường Science City Road, tại Sola (Ahmedabad), và thuộc tập đoàn Marengo Asia Hospitals. Đây là bệnh viện xanh đa siêu chuyên khoa được NABH, NABL và JCI công nhận. Vào tháng 10 năm 2023, đội ngũ do bác sĩ Dhiren Shah dẫn dắt đã thực hiện điều được giới thiệu là ca ghép tim không truyền máu đầu tiên tại châu Á, sử dụng phác đồ quản lý chảy máu theo mục tiêu; bệnh nhân xuất viện sau chín ngày so với thông thường là 21 đến 24 ngày.\n##specialities\nBệnh viện cung cấp chăm sóc ung thư, khoa học tim mạch, tiêu hóa, ghép gan và khoa học đường mật, chỉnh hình và thay khớp, khoa học thận, thần kinh, ghép tủy xương, phẫu thuật giảm béo, tâm lý học lâm sàng, thấp khớp, bàn chân đái tháo đường, nha khoa và da liễu. Bác sĩ Dhiren Shah, giám đốc chương trình ghép tim và là bác sĩ phẫu thuật ghép tim đầu tiên tại Gujarat, có hơn 16.000 ca phẫu thuật bắc cầu mạch vành và khoảng 50 ca ghép tim, là người đầu tiên tại Ấn Độ thực hiện TAVR xuyên động mạch chủ và bắc cầu kết hợp. Bệnh viện có trung tâm ghép tạng riêng cho tim, gan, thận, phổi và ghép tủy xương nhi khoa.\n##technology\nBệnh viện được mô tả là cơ sở 300–500 giường, đối diện Shukan Mall, với hồi sức tích cực và phòng mổ tiên tiến.\n##international\nBệnh viện điều trị bệnh nhân từ Ấn Độ và nước ngoài.",
	'sterling-hospital':
		"##history\nSterling Hospitals tại Gurukul, Memnagar (Ahmedabad), được thành lập năm 2001 với tư cách là bệnh viện chăm sóc chuyên sâu và đã phát triển thành mạng lưới bệnh viện khắp Gujarat. Năm 2009, bệnh viện trở thành bệnh viện đầu tiên tại Gujarat được NABH công nhận toàn diện, và phòng xét nghiệm của bệnh viện là phòng đầu tiên trong bang được NABL công nhận. Bệnh viện được IMRB và The Week vinh danh Bệnh viện Tốt nhất trong ba năm liên tiếp (2007 đến 2009).\n##specialities\nSterling cung cấp khoa học tim mạch, ung bướu (phẫu thuật, nội khoa và xạ trị), hồi sức tích cực và hô hấp, tiêu hóa và phẫu thuật tiêu hóa, thần kinh và phẫu thuật cột sống, thận học và tiết niệu, chỉnh hình và thay khớp, sản phụ khoa, huyết học, chăm sóc chấn thương, phẫu thuật giảm béo, tai mũi họng và gây mê. Bệnh viện đã thực hiện ca ghép gan đầu tiên tại khu vực, giới thiệu lọc máu CRRT, và thành lập đơn vị tủy xương đầu tiên tại Gujarat cùng cơ sở lọc máu lớn nhất bang. Bệnh viện được công nhận là trung tâm tim mạch hàng đầu tại Ahmedabad.\n##technology\nBệnh viện có khoảng 300 giường. Các đơn vị hồi sức tích cực nhi khoa và sơ sinh được trang bị theo dõi đa thông số, máy thở và ECMO cùng tỷ lệ điều dưỡng trên bệnh nhân cao.\n##international\nSterling cho biết điều trị hơn 20.000 bệnh nhân quốc tế mỗi năm từ hơn 130 quốc gia, thông qua dịch vụ một cửa cho bệnh nhân quốc tế điều phối giữa bệnh viện, bác sĩ và bệnh nhân.",
	'shalby-hospitals':
		"##history\nShalby Hospitals bắt đầu tại Ahmedabad năm 1994 với tư cách là trung tâm thay khớp do bác sĩ Vikram I. Shah khởi xướng, và trong khoảng 30 năm đã trở thành một trong những chuỗi bệnh viện chăm sóc chuyên sâu đa chuyên khoa phát triển nhanh nhất Ấn Độ tại miền tây, trung và bắc Ấn Độ. Cơ sở chủ lực tại Ahmedabad, Shalby Multispeciality Hospital, nằm trên S. G. Highway gần Ramdev Nagar, Satellite, được thành lập năm 2007. Bác sĩ Shah là chủ tịch Shalby và trưởng chương trình thay khớp từ năm 1993, nhận Dr. B. C. Roy International Award năm 2003. Năm 2025, tập đoàn nhận Hurun India Healthcare Transformation and Medical Excellence Award và giải thưởng bệnh viện tốt nhất cho du lịch y tế tại Gujarat.\n##specialities\nShalby nổi tiếng toàn cầu về thay khớp, với hơn 150.000 ca thay khớp được thực hiện. Bác sĩ Shah và đội ngũ thực hiện hơn 800 ca thay khớp lần đầu mỗi tháng, và kỹ thuật ZERO của ông đã rút ngắn thời gian phẫu thuật thay khớp gối từ khoảng 80 phút xuống còn khoảng 10–12 phút. Tập đoàn cũng nhận Rajiv Gandhi National Quality Award và các giải thưởng FICCI.\n##technology\nBệnh viện tại SG Highway được NABH và NABL công nhận, có khoảng 200 giường.\n##international\nShalby có bàn dịch vụ đặc biệt cho bệnh nhân quốc tế, cung cấp tư vấn qua video, hỗ trợ du lịch và visa, hỗ trợ chỗ ở, cùng đón và đưa miễn phí tại sân bay.",
	'dr-agarwal-s-eye-hospital':
		"##history\nDr. Agarwal's Eye Hospital được thành lập năm 1957 tại Chennai bởi Padma Bhushan bác sĩ Jaiveer Agarwal và bác sĩ Tahira Agarwal. Bác sĩ Jaiveer Agarwal nhận Padma Bhushan vào tháng 3 năm 2006. Qua nhiều thập kỷ, bệnh viện đã trở thành một trong những chuỗi chăm sóc mắt lớn nhất Ấn Độ, với các cơ sở tại 14 bang và bốn vùng lãnh thổ liên bang, cùng nhiều quốc gia ở nước ngoài, đặc biệt tại châu Phi. Số lượng cơ sở chính xác thay đổi tùy theo nguồn tin và biến động theo thời gian, vì vậy bệnh nhân nên kiểm tra danh sách hiện tại các địa điểm ở Delhi-NCR khi lên kế hoạch.\n##specialities\nBệnh viện cung cấp nhãn khoa toàn diện, bao gồm phẫu thuật đục thủy tinh thể bằng các kỹ thuật như tán nhuyễn và hỗ trợ laser femtosecond, LASIK và các phẫu thuật khúc xạ khác, chăm sóc võng mạc cho các tình trạng như bệnh võng mạc đái tháo đường và bong võng mạc, tăng nhãn áp, giác mạc và nhãn khoa nhi. Tập đoàn cũng liên kết với các bác sĩ phẫu thuật và nhà nghiên cứu nhãn khoa nổi tiếng, bao gồm bác sĩ Amar Agarwal, được biết đến với những đổi mới trong phẫu thuật đục thủy tinh thể.\n##technology\nHầu hết các thủ thuật mắt được thực hiện trong ngày, thuận tiện cho khách quốc tế. Delhi-NCR có nhiều cơ sở Dr. Agarwal's.\n##international\nVì nhiều thủ thuật mắt chỉ cần thời gian lưu trú ngắn, bệnh nhân thường có thể kết hợp điều trị với du lịch trong khu vực.",
	'laimaa-fertility-ivf-surrogacy-clinic':
		"##history\nLaimaa Fertility được thành lập năm 2022 bởi đội ngũ chuyên gia phôi học và bác sĩ giàu kinh nghiệm, tọa lạc tại E-580, Greater Kailash Part II, New Delhi. Phòng khám ra đời dưới sự dẫn dắt của chuyên gia phôi học Pooja Agarwal, bác sĩ Akanksha Chauhan và bác sĩ Mamta Chahar, cùng bác sĩ Vineet Malhotra trong đội ngũ, kết hợp chuyên môn y tế và phòng thí nghiệm. Chuyên gia phôi học Pooja Agarwal bắt đầu sự nghiệp tại Fortis Ridge IVF Centre và đã dẫn dắt các phòng thí nghiệm thụ tinh trong ống nghiệm tại nhiều cơ sở, bao gồm Gurugram và Noida, và là chuyên gia phôi học được chứng nhận về sinh thiết phôi.\n##specialities\nPhòng khám cung cấp thụ tinh trong ống nghiệm, ICSI, bơm tinh trùng vào buồng tử cung, đông lạnh trứng và phôi, hiến trứng, kế hoạch dùng thuốc tùy chỉnh, các thủ thuật phẫu thuật xâm lấn tối thiểu cho hiếm muộn và liệu pháp hormone. Phòng khám nổi tiếng về xử lý các trường hợp khó như AMH thấp và hiếm muộn nam nghiêm trọng, và đội ngũ phôi học thực hiện TESA-ICSI, PICSI, chuyển phôi nang và đông lạnh trứng, phôi. Bệnh nhân thường khen ngợi bác sĩ Akanksha Chauhan vì sự tử tế, kiến thức và sự sẵn sàng.\n##technology\nPhòng khám sử dụng các kỹ thuật sinh sản tiên tiến và nhấn mạnh vào chăm sóc cá nhân hóa cùng thực hành đạo đức. Là một phòng khám mới hơn, hoạt động như một trung tâm hiếm muộn tập trung với phòng thí nghiệm phôi học nội bộ.\n##international\nPhòng khám cung cấp tư vấn bằng tiếng Anh và tiếng Hindi. Greater Kailash Part II là khu vực được phục vụ tốt tại South Delhi, có khách sạn và kết nối tàu điện ngầm.",
	'gaudium-ivf':
		"##history\nGaudium IVF and Women Health được thành lập năm 2009 bởi bác sĩ Manika Khanna, chuyên gia hiếm muộn và bác sĩ phẫu thuật nội soi được công nhận toàn cầu với hơn 20 năm kinh nghiệm điều trị hiếm muộn. Bà nhận Delhi Ratan Award năm 2008 từ Tổng thống Ấn Độ khi đó, và được vinh danh với các giải thưởng bao gồm Rajiv Gandhi Excellence Award và Women Achievers' Award. Gaudium hiện có khoảng 36 trung tâm tại sáu bang của Ấn Độ và các trung tâm tại các nước khác, cho biết có em bé Gaudium khỏe mạnh tại hơn 30 quốc gia.\n##specialities\nTrung tâm cung cấp thụ tinh trong ống nghiệm, đông lạnh trứng và đông lạnh phôi, nổi tiếng về điều trị thất bại thụ tinh trong ống nghiệm nhiều lần, hiếm muộn nam, lạc nội mạc tử cung và thai kỳ nguy cơ cao. Bác sĩ Khanna cho biết có hơn 10.000 ca điều trị thụ tinh trong ống nghiệm dưới tên mình, và các phòng khám của tập đoàn được mô tả là phòng khám siêu chuyên khoa với chăm sóc đa chuyên khoa và chuyên gia phôi học giàu kinh nghiệm.\n##technology\nHệ sinh thái phôi học của Gaudium sử dụng công cụ dựa trên AI, bao gồm SiD để đánh giá tinh trùng và ERICA để đánh giá phôi, tại trung tâm của khuôn khổ Signature Lab kết hợp phôi học tiên tiến với tiêu chuẩn chất lượng chuẩn quốc tế. Phòng khám Delhi nằm tại M-1, tầng một, South Extension Part 2.\n##international\nGaudium đã điều trị các cặp đôi từ hơn 30 quốc gia. South Extension là khu vực thương mại nhộn nhịp tại South Delhi, kết nối tốt với tàu điện ngầm.",
	'pristyn-care-ferticity-super-speciality-ivf-hospital':
		"##history\nPristyn Care Ferticity Super Speciality & IVF Hospital tọa lạc tại 12, Navjeevan Vihar, Geetanjali Enclave, Malviya Nagar, New Delhi, và cho biết đã giúp hơn 40.000 gia đình trên toàn thế giới. Đồng sáng lập kiêm giám đốc, bác sĩ Ila Gupta, có hơn 29 năm kinh nghiệm điều trị hiếm muộn và các kỹ thuật hỗ trợ sinh sản, đã xử lý hơn 5.500 ca phức tạp, và nhận Dr. APJ Abdul Kalam Health Award năm 2023. Phòng khám được liệt kê trong Danh bạ Phòng khám ART của ICMR.\n##specialities\nBệnh viện được thiết kế cho các cặp đôi tìm kiếm thụ tinh trong ống nghiệm, bơm tinh trùng vào buồng tử cung, ICSI, đông lạnh trứng, phôi và điều trị dựa trên người hiến. Bệnh viện quản lý hội chứng buồng trứng đa nang, tắc vòi trứng, dự trữ buồng trứng thấp, hiếm muộn nam, lạc nội mạc tử cung và sảy thai liên tiếp, đồng thời cung cấp kích thích rụng trứng và đánh giá chi tiết về hormone và sức khỏe sinh sản. Bác sĩ Gupta cho biết tỷ lệ thành công lên đến 78% sử dụng các kỹ thuật như liệu pháp huyết tương giàu tiểu cầu và sàng lọc di truyền, dù kết quả khác nhau tùy bệnh nhân.\n##technology\nTất cả các chuyên gia hiếm muộn đều đăng ký với hội đồng y khoa, và phòng khám hoạt động như bệnh viện siêu chuyên khoa và thụ tinh trong ống nghiệm với cơ sở phẫu thuật, phòng thí nghiệm phôi học và hỗ trợ tư vấn. Phòng khám mở cửa từ thứ Hai đến thứ Bảy.\n##international\nPhòng khám đã điều trị các cặp đôi quốc tế, bao gồm bệnh nhân đến từ Hoa Kỳ để thụ tinh trong ống nghiệm với bác sĩ Gupta. Malviya Nagar gần ga tàu điện ngầm Malviya Nagar, tại South Delhi.",
	'nova-ivf-fertility-centre-rajouri-garden':
		"##history\nTrung tâm Nova IVF Fertility tại Rajouri Garden là một trong các phòng khám của tập đoàn tại Delhi, tại GN-14, Shivaji Enclave, Sector G, Mehta Chowk, gần ga tàu điện ngầm Rajouri Garden. Nova IVF Fertility được thành lập năm 2011, và tập đoàn nhận giải Best IVF Chain in India tại ET Healthworld National Fertility Awards năm 2021 và giải IVF/Fertility Champion of the Year năm 2025. Tập đoàn cho biết có hơn 85.000–100.000 ca sinh sống nhờ thụ tinh trong ống nghiệm trên toàn mạng lưới.\n##specialities\nPhòng khám cung cấp bơm tinh trùng vào buồng tử cung, thụ tinh trong ống nghiệm, ICSI và chọn lọc tinh trùng MACS, đông lạnh trứng, chương trình hiến tặng và chẩn đoán tiên tiến, điều trị hiếm muộn nam, hiếm muộn không rõ nguyên nhân, dự trữ buồng trứng thấp, hội chứng buồng trứng đa nang, lạc nội mạc tử cung và hiếm muộn do vòi trứng. Bác sĩ Aswati Nair là chuyên gia thụ tinh trong ống nghiệm hoàn thành MBBS tại Mumbai và MD về sản phụ khoa, sau đó là FNB về y học sinh sản, với hơn 17 năm kinh nghiệm. Bà giành giải bài báo hay nhất tại chi nhánh Kerala của ISAR về nghiên cứu keo dính phôi trong thất bại làm tổ nhiều lần. Bác sĩ Meenakshi Banerjee, bác sĩ phụ khoa với hơn 20 năm kinh nghiệm, cũng làm việc tại đây.\n##technology\nGiống như các phòng khám Nova IVF khác tại Delhi NCR, nơi đây có phòng thí nghiệm phôi học tiên tiến, phòng mổ hiện đại và khu hồi phục thoải mái, tuân theo các phác đồ quốc tế. Phòng khám mở cửa từ thứ Hai đến thứ Bảy.\n##international\nRajouri Garden kết nối tốt bằng tàu điện ngầm với trung tâm Delhi và tuyến ra sân bay.",
	'elixir-fertility-centre':
		"##history\nElixir Fertility Centre được thành lập năm 2014, là phòng khám thụ tinh trong ống nghiệm và hiếm muộn tại bắc Delhi, tại Vardhman Royal Plaza, Plot 5, LSC Gujranwala Town-1. Mục tiêu là kết hợp các chuyên gia hiếm muộn giàu kinh nghiệm với công nghệ tiên tiến để cải thiện tỷ lệ thành công, và các chuyên gia thụ tinh trong ống nghiệm cùng chuyên gia phôi học của phòng khám được đào tạo tại các trung tâm hàng đầu ở Vương quốc Anh, Đức, Singapore và Ấn Độ.\n##specialities\nPhòng khám cung cấp thụ tinh trong ống nghiệm, ICSI, bơm tinh trùng vào buồng tử cung, phân tích tinh dịch và sàng lọc di truyền. Đội ngũ bao gồm bác sĩ Puneet Kochhar, chuyên gia thụ tinh trong ống nghiệm từng làm việc tại Bourn Hall Clinic ở Cambridge, Vương quốc Anh, và giảng dạy tại Lady Hardinge Medical College ở Delhi; bác sĩ Pranay Ghosh, giám đốc kiêm chuyên gia tư vấn hiếm muộn, được đào tạo tại các trung tâm bao gồm NURTURE ở Nottingham, NUH CREST ở Singapore và Centre of Reproductive Medicine ở Kiel, hoàn thành bằng thạc sĩ tại Anh với danh hiệu xuất sắc; bác sĩ Rajiv Singla, chuyên gia nội tiết sinh sản; và bác sĩ Teita Ghosh, chuyên gia di truyền lâm sàng và miễn dịch sinh sản.\n##technology\nPhòng khám có phòng thí nghiệm chẩn đoán, siêu âm, dịch vụ cấp cứu và bãi đậu xe, hoạt động từ thứ Hai đến thứ Bảy khoảng 9 giờ sáng đến 6 giờ chiều. Phòng khám cho biết tỷ lệ thành công thụ tinh trong ống nghiệm trong khoảng 65–75%, sẽ khác nhau tùy hoàn cảnh mỗi người.\n##international\nGujranwala Town ở bắc Delhi gần Model Town và Kamla Nagar, có thể đến bằng tàu điện ngầm từ trung tâm Delhi.",
	'femmenest-fertility-ivf-centre':
		"##history\nFemmenest là trung tâm chăm sóc sức khỏe phụ nữ cao cấp tại đông Delhi cung cấp thụ tinh trong ống nghiệm, hiếm muộn và phụ khoa, tại C-52 UGF, Anand Vihar, đối diện Pushpanjali Medical Centre. Trung tâm do bác sĩ Sowjanya Aggarwal đứng đầu, chuyên gia thụ tinh trong ống nghiệm và bác sĩ phẫu thuật nội soi phụ khoa và robot với hơn 20 năm kinh nghiệm lâm sàng. Bà hoàn thành MS về sản phụ khoa tại Sri Ramachandra University, Chennai, sau đó là học bổng về phẫu thuật phụ khoa xâm lấn tối thiểu và y học sinh sản tại Kochi, và nhận Dr. Jagdishwari Mishra Oration Award năm 2012.\n##specialities\nTrung tâm cung cấp thụ tinh trong ống nghiệm, bơm tinh trùng vào buồng tử cung và ICSI, hỗ trợ cá nhân hóa cho các cặp đôi, chăm sóc hiếm muộn toàn diện từ chẩn đoán đến liệu pháp hormone, và chăm sóc phụ khoa tiên tiến cho hội chứng buồng trứng đa nang, rối loạn hormone, các vấn đề về sinh sản và khám sức khỏe phụ nữ định kỳ, cùng y học thai nhi. Trung tâm có đội ngũ bác sĩ cao cấp, chuyên gia phôi học lâm sàng, nhân viên hỗ trợ và y tá riêng.\n##technology\nTrung tâm được trang bị cơ sở hiện đại cho chăm sóc toàn diện sức khỏe phụ nữ. Trung tâm thường mở cửa từ thứ Hai đến thứ Bảy từ 9 giờ sáng đến 8 giờ tối và sáng Chủ nhật, được bệnh nhân đánh giá rất cao.\n##international\nAnand Vihar kết nối tốt bằng tàu điện ngầm cùng ga tàu và bến xe Anand Vihar, thuận tiện cho du khách đến từ các thành phố khác.",
	'india-ivf-clinic':
		"##history\nIndia IVF Clinic tại Vasant Vihar là phòng khám hiếm muộn thuộc mạng lưới Fortis. Phòng khám hoạt động tư vấn tại Fortis Flt. Lt. Rajan Dhall Hospital ở Vasant Kunj, và được liệt kê tại địa chỉ 35, Second Floor, Community Centre, Basant Lok, Vasant Vihar. Phòng khám đã hoạt động trong lĩnh vực y tế khoảng 12 năm và được bệnh nhân đánh giá rất cao.\n##specialities\nBác sĩ Richika Sahay dẫn dắt đội ngũ hiếm muộn. Bà có hơn 20 năm kinh nghiệm là chuyên gia hiếm muộn và bác sĩ phẫu thuật nội soi phụ khoa, là chuyên gia nội tiết sinh sản được chứng nhận và chuyên gia phụ về hiếm muộn (thụ tinh trong ống nghiệm-ICSI), tốt nghiệp trường y với huy chương vàng và nhận giải thưởng Chuyên gia Thụ tinh trong Ống nghiệm Trẻ Tốt nhất năm 2018. Các lĩnh vực chuyên môn của bà bao gồm thụ tinh trong ống nghiệm và ICSI, đông lạnh trứng và phôi, kích thích rụng trứng, bơm tinh trùng vào buồng tử cung, xét nghiệm và sàng lọc di truyền trước làm tổ, cùng quản lý thụ thai và sảy thai. Bà áp dụng phương pháp toàn diện, chú ý đến dinh dưỡng, lối sống và môi trường.\n##technology\nPhòng khám có thể tiếp cận bằng xe lăn và có bãi đậu xe. Bệnh nhân mô tả nhân viên thân thiện, chu đáo và hỗ trợ, đề cập đến các trường hợp mang thai và sinh nở thành công.\n##international\nVì đội ngũ cũng làm việc tại Fortis Vasant Kunj, gần sân bay quốc tế, các cặp đôi quốc tế có thể kết hợp tư vấn hiếm muộn với một bệnh viện đa chuyên khoa được trang bị tốt.",
	'spruce-dental':
		"##history\nSpruce Dental tại Jasola Vihar (South Delhi) thuộc nhóm phòng khám Spruce Dental, do bác sĩ chuyên khoa cấy ghép và chỉnh nha Javed Rizwan lãnh đạo, là phòng khám được chứng nhận ISO 9001:2015. Phòng khám nằm tại 122, Pocket 2, Jasola, gần trường DAV, được bệnh nhân đánh giá tốt. Bác sĩ Rizwan có bằng BDS và MDS và theo học thạc sĩ về cấy ghép chiến lược tại Munich, Đức, nơi ông được đào tạo bởi một người tiên phong về cấy ghép corticobasal. Ông có hơn 15.000 implant dưới tên mình và hơn 500 ca cấy ghép toàn hàm tức thì.\n##specialities\nPhòng khám cung cấp điều trị tủy răng không đau để cứu răng bị hư hại, cấy ghép răng toàn hàm cho răng bị mất, cấy ghép răng đơn, tẩy trắng răng chuyên nghiệp, các lựa chọn chỉnh nha tiên tiến và cải thiện nụ cười với nha khoa thẩm mỹ. Nhóm điều hành các chương trình nội trú lâm sàng về nha khoa tổng quát và cấy ghép.\n##technology\nHình ảnh kỹ thuật số cho hình ảnh rõ ràng về răng và nướu để lập kế hoạch điều trị tốt hơn, và phòng khám hướng đến cung cấp dịch vụ chăm sóc răng miệng đạo đức, lấy bệnh nhân làm trung tâm trong môi trường thoải mái.\n##international\nJasola Vihar gần Indraprastha Apollo Hospital và các ga tàu điện ngầm Jasola tại South Delhi. Công việc cấy ghép răng và thiết kế nụ cười thường được lên kế hoạch trong một số ít lần khám.",
	'zemya-ivf-fertility-clinics':
		"##history\nZemya IVF & Fertility Clinics là trung tâm hiếm muộn tại C-10, Green Park Extension, New Delhi, được mô tả là một trong những trung tâm thụ tinh trong ống nghiệm hàng đầu tại Delhi NCR. Trung tâm cung cấp dịch vụ chăm sóc đồng cảm, lấy bệnh nhân làm trung tâm, cho biết đã giúp hơn 50.000 cặp đôi. Đội ngũ bao gồm các chuyên gia thụ tinh trong ống nghiệm được đào tạo toàn cầu và chuyên gia phôi học được chứng nhận ESHRE, bao gồm một chuyên gia phôi học cao cấp kiêm quản lý phòng thí nghiệm thụ tinh trong ống nghiệm với hơn 15 năm kinh nghiệm về phôi học lâm sàng và công nghệ hỗ trợ sinh sản.\n##specialities\nZemya cung cấp thụ tinh trong ống nghiệm, ICSI và bơm tinh trùng vào buồng tử cung, chăm sóc hiếm muộn nam, đông lạnh trứng và bảo tồn khả năng sinh sản dưới một mái nhà, với kế hoạch điều trị cá nhân hóa. Các trang điều trị của trung tâm trình bày chi tiết về thụ tinh trong ống nghiệm, ICSI và hiếm muộn nam.\n##technology\nCơ sở vật chất bao gồm phòng chờ rộng rãi, phòng hồi phục riêng và sang trọng, phòng mổ theo mô-đun, phòng thí nghiệm thụ tinh trong ống nghiệm hiện đại, phòng thí nghiệm nam khoa tiên tiến cho xét nghiệm hiếm muộn nam, nhà thuốc riêng, phòng thí nghiệm giải phẫu bệnh, phòng chờ dành cho bệnh nhân quốc tế, phòng tư vấn, phòng hội nghị và dịch vụ tư vấn qua video.\n##international\nGreen Park là khu vực kết nối tốt tại South Delhi với kết nối tàu điện ngầm, khách sạn và nhà hàng, và phòng khám có phòng chờ dành cho bệnh nhân quốc tế.",
	'kokilaben-dhirubhai-ambani-hospital':
		"##history\nKokilaben Dhirubhai Ambani Hospital, trên đường Rao Saheb Achutrao Patwardhan Marg tại Andheri West (Mumbai), đi vào hoạt động đầu năm 2009 với tư cách là bệnh viện đa chuyên khoa 750 giường. Bệnh viện phục vụ Mumbai, các vùng lân cận và bệnh nhân quốc tế, được JCI, NABH và CAP công nhận. Năm 2025, bệnh viện được vinh danh Bệnh viện Tốt nhất – Quốc gia trong sáu hạng mục (đa chuyên khoa, ung bướu, phẫu thuật robot, thần kinh, chỉnh hình và phục hồi chức năng) tại Financial Express Healthcare Summit and Awards, và nhận NABH Digital Health Excellence Award.\n##specialities\nBệnh viện cho biết đã thực hiện hơn 21.000 ca phẫu thuật ung thư phức tạp, hơn 280 ca ghép gan và hơn 3.600 ca phẫu thuật robot, do đội ngũ hơn 400 bác sĩ thực hiện. Trung tâm Phẫu thuật Robot, thành lập năm 2012, được mô tả là nhanh nhất đạt 1.000 ca phẫu thuật robot trong 48 tháng kể từ khi ra mắt. Ung bướu, thần kinh, chỉnh hình, khoa học tim mạch, ghép tạng và phục hồi chức năng nằm trong số các thế mạnh chính.\n##technology\nBệnh viện có khoảng 180 giường hồi sức tích cực và là nơi ghi nhận nhiều điều đầu tiên, bao gồm phòng MRI trong phẫu thuật ba phòng đầu tiên tại châu Á (IMRIS), hệ thống xạ phẫu EDGE của Varian đầu tiên tại châu Á và phòng phẫu thuật cột sống có cánh tay O đầu tiên tại Ấn Độ. Bệnh viện sử dụng da Vinci Xi và hệ thống phẫu thuật robot Toumai đầu tiên tại Ấn Độ, cung cấp hình ảnh 3D HD và khả năng phẫu thuật từ xa.\n##international\nKokilaben nổi tiếng về chăm sóc bệnh nhân quốc tế, với dịch vụ tiếp tân và hỗ trợ cho mọi nhu cầu du lịch y tế. Andheri West gần tàu điện ngầm và sân bay quốc tế Mumbai.",
	'p-d-hinduja-hospital':
		"##history\nP. D. Hinduja Hospital được thành lập năm 1951 bởi Parmanand Deepchand Hinduja hợp tác với Massachusetts General Hospital, bệnh viện giảng dạy chính của Harvard Medical School, và chuyển đến tòa nhà East Wing tại địa điểm Mahim năm 1963, biến đổi từ cơ sở ngoại trú khiêm tốn thành một bệnh viện toàn diện. Bệnh viện nằm trên đường Veer Savarkar Marg, gần Shivaji Park. Đây là bệnh viện đầu tiên tại Ấn Độ nhận Green and Clean Hospital Platinum Certificate từ Bureau Veritas, và giành các giải thưởng bao gồm IMC Ramkrishna Bajaj National Award về chất lượng y tế.\n##specialities\nBệnh viện cung cấp dịch vụ tại hơn 45 chuyên khoa trừ sản khoa, với 53 giường hồi sức tích cực, 19 đơn vị điều trị trong ngày, 170 bác sĩ tư vấn và hơn 800 y tá cùng nhân viên khác, cùng một trung tâm sàng lọc sức khỏe. Đây là bệnh viện tư nhân đầu tiên tại Mumbai thực hiện ca ghép thận từ người hiến đã qua đời và ghép tế bào gốc máu ngoại vi, và là bệnh viện đầu tiên tại Ấn Độ thực hiện mở sọ khi tỉnh cho phẫu thuật động kinh. Tim mạch, ung bướu, thần kinh và chỉnh hình nằm trong số các thế mạnh chính.\n##technology\nBệnh viện tổ chức các khóa DNB tại 26 chuyên khoa, các chương trình thạc sĩ và tiến sĩ, một trường điều dưỡng và các khóa học y tế liên quan, hợp tác với các cơ sở như Hôpitaux Universitaires de Genève, Stanford University và Henry Ford Health. Bệnh viện được NABH công nhận.\n##international\nBệnh viện có bộ phận dịch vụ riêng cho bệnh nhân quốc tế để giúp lập kế hoạch và điều phối điều trị. Mahim kết nối tốt bằng đường sắt và đường bộ với trung tâm Mumbai và sân bay.",
	'fortis-hospital-mulund':
		"##history\nFortis Hospital, Mulund, khai trương năm 2002, là bệnh viện đa chuyên khoa chăm sóc cấp bốn 400 giường trên đường Mulund–Goregaon Link Road. Bệnh viện được mô tả là bệnh viện đầu tiên tại Ấn Độ và Nam Á nhận chứng nhận JCI, và là bệnh viện duy nhất tại miền tây Ấn Độ với bảy lần chứng nhận JCI liên tiếp. Đây là bệnh viện đầu tiên cả nước nhận chứng nhận NABH cho dịch vụ cấp cứu và là bệnh viện đầu tiên tại Ấn Độ ra mắt ICU điện tử. Bệnh viện đã giành hơn 250 giải thưởng về xuất sắc y tế.\n##specialities\nFortis Mulund là nơi đặt trung tâm ghép đa tạng lớn nhất Maharashtra, bao phủ thận, gan, tim và tủy xương. Đây là bệnh viện đầu tiên tại miền tây Ấn Độ hoàn thành hơn 100 ca ghép tim chỉ trong bốn năm và hoàn thành ca ghép tủy xương thứ 100 năm 2024. Chương trình thần kinh với hình ảnh thần kinh tiên tiến và các đơn vị hồi sức thần kinh tích cực được coi là một trong những chương trình tốt nhất Ấn Độ, và bệnh viện cũng cung cấp khoa học tim mạch, ung bướu, thận học, tiết niệu, chỉnh hình, tiêu hóa, cấp cứu và hồi sức tích cực, cùng chăm sóc sản khoa.\n##technology\nBệnh viện có 108 giường hồi sức tích cực, sáu đơn vị ghép tủy xương riêng và một trung tâm chấn thương Cấp 1. Ung bướu sử dụng máy gia tốc tuyến tính Versa HD, và bệnh viện là một trong số ít cơ sở tại quốc gia có nền tảng xạ trị này.\n##international\nFortis Mulund vận hành Đơn vị Bệnh nhân Quốc tế 24/7 hỗ trợ bệnh nhân và gia đình trong suốt quá trình y tế. Bệnh viện nằm tại vùng ngoại ô phía đông Mumbai, gần ga đường sắt Mulund.",
	'jaslok-hospital':
		"##history\nJaslok Hospital & Research Centre, trên đường Dr. G. Deshmukh Marg tại Peddar Road, được thành lập bởi nhà từ thiện Seth Lokoomal Chanrai và bác sĩ phẫu thuật Shantilal Jamnadas Mehta, khánh thành ngày 6 tháng 7 năm 1973 bởi Thủ tướng Indira Gandhi. Đây là một trong những bệnh viện quỹ đa chuyên khoa chăm sóc chuyên sâu lâu đời nhất Ấn Độ, đã kỷ niệm 50 năm phục vụ với Navbharat Healthcare Award năm 2022.\n##specialities\nBệnh viện có khoảng 50 chuyên khoa và gần 20 phòng khám chuyên khoa, với hơn 350 giường bao gồm hơn 75 giường hồi sức tích cực. Bệnh viện thực hiện ca ghép thận đầu tiên tại một bệnh viện tư nhân ở Ấn Độ năm 1974, khởi động khoa tiết niệu tư nhân đầu tiên tại Ấn Độ, và đạt được ca ghép gan tư nhân đầu tiên tại Mumbai năm 1998 cùng ca ghép gan nhi khoa đầu tiên tại miền tây Ấn Độ. Bệnh viện giới thiệu máy gamma camera ba đầu dò đầu tiên và máy quay tim thể rắn đầu tiên tại Ấn Độ, và là bệnh viện đầu tiên tại Mumbai áp dụng siêu âm tim 2D, điện sinh lý và stent phủ thuốc. Trong y học sinh sản, bệnh viện cho biết có ca chuyển phôi hỗ trợ cumulus đầu tiên trên thế giới trong thụ tinh trong ống nghiệm, và giành giải Phòng khám Thụ tinh trong Ống nghiệm Tốt nhất tại ET Healthcare Fertility Awards năm 2019.\n##technology\nBệnh viện được NABH (phiên bản thứ 5), NABL công nhận và có chứng nhận ISO 9001, 14001 và 45001, cùng chứng nhận xuất sắc về điều dưỡng và ủy ban đạo đức NABH.\n##international\nJaslok hỗ trợ bệnh nhân quốc tế, bao gồm tư vấn trước khi đến và lập kế hoạch chi phí với tư vấn từ xa và kế hoạch điều trị chi tiết, cùng hỗ trợ visa và du lịch. Bệnh viện nằm ở nam Mumbai, gần Mahalaxmi.",
	'nanavati-max-super-speciality-hospital':
		"##history\nNanavati Max Super Speciality Hospital tại Vile Parle được khánh thành vào tháng 11 năm 1950 bởi Thủ tướng đầu tiên của Ấn Độ, Jawaharlal Nehru, được Mahatma Gandhi ban phước, và mở cửa cho bệnh nhân năm 1951. Bệnh viện là trụ cột của ngành y tế Mumbai hơn 70 năm và nay là một phần của Max Healthcare. Bệnh viện có 350 giường, hơn 350 bác sĩ tư vấn, hơn 100 bác sĩ nội trú, khoảng 475 nhân viên điều dưỡng và khoảng 1.500 nhân viên.\n##specialities\nBệnh viện có 55 khoa chuyên môn và các trung tâm xuất sắc về tim mạch, ung bướu, thận học, chỉnh hình, phẫu thuật cột sống, thần kinh, giảm béo và tiêu hóa ngoại khoa. Bệnh viện cũng cung cấp vật lý trị liệu, da liễu, phẫu thuật thẩm mỹ, thần kinh nhi khoa, hô hấp, phẫu thuật cột sống xâm lấn tối thiểu, ghép tủy xương, sản phụ khoa, chăm sóc tiêu hóa và gan, phẫu thuật tổng quát và nội soi, thay khớp và thần kinh. Bệnh viện ra mắt Trung tâm Phẫu thuật Robot năm 2019 và giới thiệu liệu pháp bút và bơm apomorphine cho bệnh Parkinson hợp tác với King's College London năm 2018.\n##technology\nTrung tâm hình ảnh trải rộng hơn 10.000 feet vuông với MRI 3 Tesla ống rộng và máy quét PET-CT 64 lát cắt có khả năng tim mạch. Bệnh viện được NABH và NABL công nhận, giành các giải thưởng bao gồm Bệnh viện Tốt nhất về An toàn Bệnh nhân (2021) và Bệnh viện của Năm về Ghép Tạng (2024).\n##international\nBệnh viện có Bàn Bệnh nhân Quốc tế riêng cung cấp đón và tiễn miễn phí tại sân bay, hỗ trợ visa, điều phối bảo hiểm du lịch y tế, phiên dịch viên và biên dịch, đổi ngoại tệ và các bữa ăn tùy chỉnh. Bệnh viện nằm tại Vile Parle West, gần sân bay nội địa và quốc tế của Mumbai.",
	'apollo-hospitals-greams-road':
		"##history\nApollo Hospitals, Greams Road, được khởi động năm 1983 bởi bác sĩ Prathap C. Reddy với tư cách là bệnh viện tư nhân được quản lý chuyên nghiệp đầu tiên tại Ấn Độ với 150 giường, và là bệnh viện tập đoàn đầu tiên của đất nước, đóng vai trò quan trọng trong việc chuyển đổi hệ thống y tế tư nhân. Bác sĩ Reddy được trao Padma Vibhushan và các giải thưởng thành tựu trọn đời từ ba tập đoàn truyền thông. Ngày nay bệnh viện có 550 giường, được JCI và NABH công nhận và được coi rộng rãi là một trong những bệnh viện tốt nhất Ấn Độ cho bệnh nhân quốc tế.\n##specialities\nBệnh viện có hơn 12 trung tâm xuất sắc, bao gồm Apollo Heart Institute, Institute of Liver Sciences, Institute of Neurosciences, Institute of Colorectal Surgery và Institute of Robotic Surgery. Chương trình ghép tạng của bệnh viện bao phủ gan, thận, tim và phổi, với các dấu mốc như ca ghép tụy thành công đầu tiên tại Ấn Độ và ca ghép tim và gan kết hợp en-bloc đầu tiên tại châu Á. Bệnh viện là bệnh viện đầu tiên tại Ấn Độ giới thiệu nong mạch vành, xạ trị định vị và xạ phẫu cho u não.\n##technology\nCông nghệ bao gồm hệ thống phẫu thuật robot da Vinci, ExcelsiusGPS cho phẫu thuật cột sống, TrueBeam STx cho xạ trị, CyberKnife đầu tiên tại Ấn Độ và việc sử dụng PET-CT 64 lát cắt tại Đông Nam Á. Trung tâm xạ trị proton được mô tả là trung tâm đầu tiên tại Ấn Độ và tiên tiến nhất Nam Á.\n##international\nApollo Chennai được công nhận là Công ty Hứa hẹn Nhất về Dịch vụ Y tế Quốc tế (MT India Healthcare Awards, 2023). Bệnh viện nằm trên đường Greams Lane, gần Greams Road, trung tâm Chennai, gần các khách sạn.",
	'miot-international':
		"##history\nMIOT International, Madras Institute of Orthopaedics and Traumatology, được thành lập bởi Padmashri Giáo sư bác sĩ P. V. A. Mohandas vào ngày 12 tháng 2 năm 1999 với tư cách là bệnh viện 70 giường tập trung vào chỉnh hình và chăm sóc chấn thương. Bác sĩ Mohandas thực hiện ca thay khớp hông đầu tiên tại Ấn Độ và nhận Padmashri năm 1992 vì tiên phong trong lĩnh vực thay khớp. Bệnh viện đã phát triển thành cơ sở chăm sóc cấp bốn 1.000 giường tại Manapakkam với 63 chuyên khoa và 21 phòng mổ, tiếp đón bệnh nhân từ hơn 130 quốc gia.\n##specialities\nKhoa chỉnh hình và thay khớp của MIOT được Outlook Health xếp hạng đứng đầu Ấn Độ, với hơn 40.000 ca thay khớp hông, gối và chi trên. Các dấu mốc bao gồm ca phẫu thuật lỗ khóa đầu tiên, ca ghép thận khác nhóm máu đầu tiên tại Ấn Độ, ca ghép tủy xương đơn bội tương hợp đầu tiên tại Ấn Độ và hệ thống lắp đặt xạ trị TrueBeam STx đầu tiên tại châu Á Thái Bình Dương. Từ năm 2012, MIOT International Centre đặt ung bướu, xạ trị ung thư, trung tâm ghép gan và trung tâm ghép tủy xương, cùng tim mạch, thận học, phẫu thuật thần kinh, phẫu thuật thẩm mỹ, nhi khoa và sản khoa.\n##technology\nBệnh viện được NABH và NABL công nhận và giành các giải thưởng bao gồm Times Healthcare Legends in Orthopaedics và Bệnh viện Đa chuyên khoa Tốt nhất Chennai (2018), Radio City ICON Award (2019) và Times Healthcare Achievers Awards (2020).\n##international\nMIOT cung cấp thư mời visa, phương tiện đưa đón sân bay miễn phí và hỗ trợ phiên dịch đa ngôn ngữ. Bệnh viện nằm trên đường Mount Poonamallee Road, không xa sân bay Chennai.",
	'gleneagles-global-health-city':
		"##history\nGleneagles Global Health City tại Perumbakkam (Chennai) thuộc IHH Healthcare và là một trong những bệnh viện ghép đa tạng và chăm sóc cấp bốn lớn nhất Ấn Độ, trên khuôn viên 21 mẫu Anh. Viện Bệnh Gan và Ghép Tạng, thành lập năm 2009 bởi Giáo sư Mohamed Rela, đã thực hiện hơn 1.500 ca ghép gan và được coi là một trong những chương trình ghép gan lớn nhất Ấn Độ. Giáo sư Rela đã thực hiện hơn 4.000 ca ghép gan và được ghi trong Sách Kỷ lục Guinness về ca ghép gan cho một em bé năm ngày tuổi.\n##specialities\nBệnh viện có hơn 40 chuyên khoa và được công nhận quốc tế về ghép tạng, ung bướu, gan mật, thần kinh và chăm sóc chấn thương. Bệnh viện thực hiện ghép gan, thận, tim, phổi và tủy xương, cho biết là bệnh viện đầu tiên tại miền nam Ấn Độ thực hiện năm ca ghép tạng trong một ngày, bệnh viện đầu tiên tại Ấn Độ thực hiện ghép gan hoán đổi cho người lớn và ghép gan phân chia, cùng bệnh viện đầu tiên tại Ấn Độ cấy phổi nhân tạo và thực hiện ghép tử cung. Chương trình ghép phổi được coi là một trong những chương trình tốt nhất Ấn Độ, và bệnh viện thực hiện ghép gan hợp tác với King's College Hospital, London.\n##technology\nBệnh viện cho biết công suất khoảng 1.000 giường và được NABH, NABL công nhận, có chứng nhận halal cho thực phẩm.\n##international\nBệnh viện hướng đến cung cấp cơ sở đạt tiêu chuẩn quốc tế với giá cả cạnh tranh, đặc biệt cho ghép đa tạng. Perumbakkam nằm ở nam Chennai gần hành lang công nghệ thông tin.",
	'fortis-malar-hospital':
		"##history\nFortis Malar Hospital tại Adyar (Chennai) được thành lập năm 1992 với tên Malar Hospital và gia nhập Fortis Healthcare năm 2007. Đây là bệnh viện đa chuyên khoa chăm sóc chuyên sâu 180 giường, cung cấp dịch vụ tại hơn 40 chuyên khoa. Bệnh viện nổi tiếng với Fortis Centre for Heart Failure and Transplant, được mô tả là trung tâm toàn diện đầu tiên tại Ấn Độ về quản lý suy tim.\n##specialities\nChương trình tim mạch của bệnh viện bao phủ tim mạch can thiệp, xâm lấn, không xâm lấn và nhi khoa, phẫu thuật tim mạch và ghép tim. Trung tâm đã hoàn thành hơn 50 ca ghép tim, cấy LVAD dài hạn và hỗ trợ ECMO tĩnh-động mạch cho suy tim nguy kịch, được ghi nhận với các ca cấy Heartmate II LVAD và HVAD thành công đầu tiên tại Ấn Độ. Bác sĩ K. R. Balakrishnan, giám đốc khoa học tim mạch, có hơn 30 năm kinh nghiệm, thực hiện hơn 16.000 ca phẫu thuật tim, và nhận FICCI Special Jury Award. Bệnh viện cũng cung cấp thần kinh, phẫu thuật thần kinh, chỉnh hình, thận học, phụ khoa, tiêu hóa, tiết niệu, nhi khoa và chăm sóc đái tháo đường.\n##technology\nBệnh viện được NABH công nhận. Số liệu về công suất giường khác nhau tùy nguồn tin, nên bệnh nhân nên xác nhận công suất hiện tại khi lên kế hoạch.\n##international\nBệnh viện điều trị bệnh nhân từ nước ngoài; một trường hợp gần đây liên quan đến ca ghép tim thành công cho một công dân Pakistan 40 tuổi. Adyar là khu dân cư yên tĩnh tại nam Chennai.",
	'kauvery-hospital':
		"##history\nKauvery Hospital tại Alwarpet, 81, TTK Road, là bệnh viện đa chuyên khoa tại trung tâm Chennai, thuộc tập đoàn Kauvery, có hơn 2.000 giường tại 10 địa điểm ở Tamil Nadu và Karnataka. Bệnh viện được Newsweek mô tả là một trong 20 bệnh viện hàng đầu Ấn Độ, và đã dành 25 năm xây dựng mạng lưới bác sĩ phẫu thuật được đào tạo quốc tế. Các bệnh viện tại Alwarpet và Vadapalani có chứng nhận JCI, được mô tả là mạng lưới duy nhất tại Ấn Độ có chứng nhận JCI kép phiên bản thứ 8.\n##specialities\nKauvery có các trung tâm xuất sắc về khoa học tim mạch, thần kinh, tiêu hóa, ghép tạng, chỉnh hình và sức khỏe phụ nữ. Kauvery Heart Institute tại Alwarpet tập trung vào nong mạch phức tạp, Impella, bắc cầu kết hợp và ghép tim. Đội ngũ ghép tim và phổi, gồm bác sĩ phẫu thuật ghép tạng, bác sĩ tim mạch chuyên về suy tim, bác sĩ hô hấp về ghép tạng, bác sĩ gây mê lồng ngực, bác sĩ hồi sức tích cực, chuyên gia tuần hoàn ngoài cơ thể và điều phối viên, được Tamil Nadu State Transplant Authority (TRANSTAN) vinh danh năm 2023.\n##technology\nKauvery Institute of Robotic Surgery cung cấp phẫu thuật robot da Vinci trong ung bướu, tiết niệu, phẫu thuật tiêu hóa, đại trực tràng và tim, phẫu thuật gan và ghép thận. Bệnh viện có khoảng 300 giường trong tòa nhà bảy tầng gần cầu vượt Alwarpet, được NABH công nhận.\n##international\nĐiều thu hút nhiều bệnh nhân quốc tế đến Kauvery là đội ngũ y tế có chuyên môn cao. Alwarpet nằm ở vị trí thuận lợi tại trung tâm Chennai gần khách sạn và nhà hàng.",
	'manipal-hospital-old-airport-road':
		"##history\nManipal Hospital, Old Airport Road, được khởi động tại Bengaluru năm 1991 với tư cách là bệnh viện tập đoàn đầu tiên của thành phố và đã trở thành cơ sở chủ lực của mạng lưới Manipal Hospitals và nền tảng của Manipal Education and Medical Group. Bệnh viện được vinh danh Bệnh viện Đa chuyên khoa Tốt nhất (Tư nhân) tại The Week Health Summit 2025 và Bệnh viện Đa chuyên khoa Tốt nhất Bengaluru tại The Week Best Hospitals Awards 2024, giành Golden Peacock National Quality Award năm 2005. Bệnh viện được NABH và JCI công nhận.\n##specialities\nBệnh viện cung cấp hơn 60 siêu chuyên khoa với các trung tâm xuất sắc về ung bướu, khoa học tim mạch, thần kinh, tiêu hóa, chỉnh hình và ghép tạng. Đây là trung tâm ghép đa tạng đã được thiết lập với các chương trình toàn diện về thận, gan, tụy, tim, phổi và tủy xương, nổi tiếng về việc sớm áp dụng ghép thận hỗ trợ robot tại Ấn Độ. Chương trình ghép tạng của mạng lưới rộng lớn hơn nằm trong số các chương trình lớn nhất cả nước.\n##technology\nBệnh viện có khoảng 600 giường hoặc hơn, bao gồm 144 giường hồi sức tích cực, và 20 phòng mổ theo mô-đun, cùng chăm sóc ung thư tiên tiến và các đơn vị ghép tạng.\n##international\nBệnh viện phục vụ bệnh nhân từ hơn 80 quốc gia và cung cấp hỗ trợ toàn diện, bao gồm tư vấn trước khi đến và lập kế hoạch điều trị với tư vấn từ xa, hỗ trợ visa và du lịch với thư mời visa y tế, đón và tiễn sân bay, chỗ ở, biên dịch và phiên dịch viên đa ngôn ngữ. Bệnh viện nằm trên đường HAL Old Airport Road.",
	'sakra-world-hospital':
		"##history\nSakra World Hospital tại Bengaluru được khởi động vào tháng 2 năm 2014, được mô tả là bệnh viện đa chuyên khoa Nhật Bản đầu tiên tại Ấn Độ và bệnh viện đầu tiên tại Ấn Độ có 100% vốn đầu tư trực tiếp nước ngoài, thuộc sở hữu và quản lý bởi liên doanh giữa Toyota Tsusho và Secom Hospitals của Nhật Bản, với sự tham gia của Kirloskar khi ra mắt. Bệnh viện kết hợp thế mạnh của Ấn Độ và Nhật Bản, và các phác đồ điều dưỡng của bệnh viện pha trộn thực hành Ấn Độ và Nhật Bản. Bệnh viện nhận Award for Excellence in Healthcare từ Indian Business Awards, sự công nhận quốc gia từ Bộ Y tế và Phúc lợi Gia đình, và National Award for Laboratory Excellence đầu tiên từ QCI. Bệnh viện cũng đạt chứng nhận AACI, với một bệnh viện thứ hai 500 giường được công bố.\n##specialities\nBệnh viện cung cấp thần kinh, tim mạch, chỉnh hình, sản phụ khoa, khoa học thận, khoa học phục hồi chức năng, nhi khoa, phẫu thuật cột sống, X-quang, tâm lý học lâm sàng, nội khoa, tai mũi họng, phẫu thuật đầu và cổ, ung thư, rối loạn máu, phẫu thuật thẩm mỹ, hô hấp, thấp khớp, nội tiết, nha khoa, da liễu, tâm thần, nhãn khoa, hồi sức tích cực, y học đau và nhiều hơn nữa. Bệnh viện nổi tiếng về tim mạch, chỉnh hình, thần kinh và ghép tạng. Sakra Institute of Rehabilitation Sciences được coi là trung tâm phục hồi chức năng lớn nhất châu Á và là trung tâm đầu tiên có chứng nhận chất lượng toàn cầu.\n##technology\nBệnh viện có 350 giường nội trú, với hình ảnh bao gồm MRI, CT đa đầu dò, siêu âm 3D và 4D, X-quang kỹ thuật số, OPG và đo mật độ khoáng xương.\n##international\nMột bộ phận dịch vụ bệnh nhân quốc tế riêng chăm sóc bệnh nhân và người đi cùng đến từ nước ngoài, với sắp xếp visa, đưa đón sân bay, chỗ ở, phiên dịch ngôn ngữ và quản lý chăm sóc cá nhân hóa. Bệnh viện nằm trên đường Outer Ring Road, gần Marathahalli và Bellandur.",
	'narayana-institute-of-cardiac-sciences':
		"##history\nNarayana Institute of Cardiac Sciences được đưa vào hoạt động năm 2000 với tư cách là một phần của NH Health City tại Bommasandra (Bengaluru) bởi bác sĩ phẫu thuật tim Devi Shetty, người sáng lập Narayana Health. Đây là trung tâm tim mạch chủ lực của Narayana Health và là một trong những bệnh viện tim mạch lớn nhất thế giới, thuộc khuôn viên được mô tả là một trong những địa điểm chăm sóc tim mạch lớn nhất thế giới. Viện đã thực hiện hơn 100.000 thủ thuật tim mạch và có đội ngũ hơn 250 bác sĩ tim mạch và chuyên gia tim. Viện được JCI và NABH công nhận.\n##specialities\nViện chuyên về phẫu thuật tim và ghép tim, đồng thời cung cấp dịch vụ điện sinh lý, cấy thiết bị hỗ trợ tâm thất trái (LVAD), cấy van động mạch chủ qua ống thông (TAVI) và chương trình cho các tình trạng tim cấu trúc. Viện thực hiện hơn 40 ca phẫu thuật tim mỗi ngày, bao gồm khoảng 16 ca phẫu thuật tim nhi khoa.\n##technology\nCơ sở có khoảng 20 phòng mổ tim, bao gồm hai phòng robot tiên tiến, và nhiều phòng can thiệp qua ống thông kỹ thuật số, bao gồm phòng lai cho các thủ thuật can thiệp và phẫu thuật tim phức tạp. Cơ sở có khoảng 200 giường hồi sức tích cực cho chăm sóc sau phẫu thuật.\n##international\nViện cách sân bay quốc tế Kempegowda khoảng 50 km, thuận tiện cho bệnh nhân đến từ các vùng khác của Ấn Độ và nước ngoài. Viện nằm trên đường Hosur Road, gần Electronic City.",
	'fortis-hospital-bannerghatta-road':
		"##history\nFortis Hospital, Bannerghatta Road, khai trương năm 2006, là bệnh viện đa chuyên khoa chủ lực của Fortis Healthcare tại miền nam Ấn Độ, đối diện IIM Bangalore. Bệnh viện được NABH (bốn lần) và JCI (năm lần) công nhận, được cho là bệnh viện đầu tiên tại Karnataka đạt chứng nhận JCI. Bệnh viện giành các giải thưởng bao gồm giải AHPI, National Energy Conservation Award (2014), Asian Patient Safety Award và chứng nhận du lịch y tế quốc tế về sự xuất sắc trong chăm sóc, được The Week xếp vào nhóm các bệnh viện đa chuyên khoa tốt nhất Bengaluru.\n##specialities\nBệnh viện cung cấp chăm sóc chuyên sâu siêu chuyên khoa tại khoảng 40 lĩnh vực y tế, với các trung tâm xuất sắc về tim mạch và phẫu thuật tim, thần kinh và phẫu thuật thần kinh, ung bướu, chỉnh hình, ghép tạng, tiêu hóa, nhi khoa và hồi sức tích cực. Khoa ung bướu cung cấp xạ trị tiên tiến, hóa trị, hội đồng khối u và ghép tủy xương, phẫu thuật ung thư bằng robot và HIFU cho ung thư tuyến tiền liệt, được hỗ trợ bởi PET-CT, PET-MR, MRI 3T và chẩn đoán phân tử. Chương trình tim mạch bao gồm nong mạch, bắc cầu, sửa van, điện sinh lý, phẫu thuật tim lai và ghép tim-phổi, và Fortis Institute of Robotic Surgery là trung tâm xuất sắc.\n##technology\nBệnh viện có khoảng 280 giường, hơn 150 bác sĩ và 800 nhân viên cận lâm sàng, với cấp cứu, ghép tạng và chăm sóc phòng ngừa.\n##international\nFortis Bannerghatta Road cung cấp dịch vụ cho bệnh nhân quốc tế với hỗ trợ visa y tế, thông dịch viên và hỗ trợ tiếp tân, cho biết đã hỗ trợ bệnh nhân từ hơn 175 quốc gia. Bệnh viện nằm trên đường Bannerghatta Road, nam Bengaluru.",
	'aster-cmi-hospital':
		"##history\nAster CMI Hospital tại Hebbal (Bengaluru) thuộc Aster DM Healthcare, một trong những mạng lưới y tế lớn nhất châu Á, hoạt động tại chín quốc gia. Các nguồn tin khác nhau về năm thành lập, nên tốt nhất mô tả đây là bệnh viện của thập niên 2010. Bệnh viện được NABH và NABL công nhận và có gần 500 giường, từ chăm sóc cơ bản đến cấp bốn. Đây là bệnh viện đầu tiên tại Bangalore được chọn làm trung tâm ghép thận cho bang Karnataka, và là bệnh viện đầu tiên tại Karnataka được FPID (Hoa Kỳ) chứng nhận là trung tâm xuất sắc về thiếu hụt miễn dịch nguyên phát.\n##specialities\nAster CMI cung cấp các trung tâm xuất sắc về khoa học tim mạch, thần kinh, tiêu hóa, chăm sóc gan tích hợp, ghép tạng, tiết niệu và thận học, chỉnh hình, sức khỏe phụ nữ và sức khỏe trẻ em, thanh thiếu niên, với hơn 38 chuyên khoa dưới một mái nhà. Chương trình ghép tạng đã thực hiện tổng cộng hơn 1.000 ca ghép thận, bao gồm 54 ca ghép thận bằng robot đến nay, sử dụng robot phẫu thuật da Vinci. Aster International Institute of Oncology cung cấp xạ trị proton, phẫu thuật robot, HIPEC và phân tích phân tử khối u.\n##technology\nBệnh viện nằm tại khu vực Hebbal trên đường sân bay, và khoa tiết niệu và thận học được xếp hạng trong số tốt nhất Bangalore theo khảo sát hồi sức tích cực của Times of India.\n##international\nĐối với bệnh nhân quốc tế, Aster CMI cung cấp điều phối riêng, đưa đón sân bay, phiên dịch viên ngoại ngữ và hỗ trợ visa. Hebbal nằm trên tuyến đường giữa trung tâm Bengaluru và sân bay quốc tế Kempegowda.",
	'apollo-hospitals-jubilee-hills':
		"##history\nApollo Hospitals, Jubilee Hills, thành lập năm 1988, là bệnh viện chủ lực của Apollo tại Hyderabad và có chứng nhận JCI. Bệnh viện được Chính phủ Ấn Độ vinh danh là bệnh viện du lịch y tế hàng đầu và nhận FICCI Healthcare Excellence Award. Bệnh viện giới thiệu máy quét PET-CT đầu tiên tại Ấn Độ năm 2005, thực hiện nong mạch vành đầu tiên tại Ấn Độ sử dụng stent hoàn toàn tự tiêu, và đã thực hiện hơn 150.000 ca phẫu thuật tim với tỷ lệ thành công được báo cáo trên 99%. Bệnh viện cũng hoàn thành hơn 700 ca cấy ốc tai điện tử.\n##specialities\nBệnh viện điều hành 12 trung tâm xuất sắc. Trung tâm khoa học tim mạch có ba phòng can thiệp qua ống thông và phòng mổ tim riêng, với phẫu thuật tim hỗ trợ robot, TAVI và các can thiệp mạch vành phức tạp. Trung tâm ung thư dựa trên 35 năm kinh nghiệm và cung cấp phẫu thuật ung thư bằng robot. Khoa thần kinh được trang bị phòng MRI trong phẫu thuật, định vị thần kinh và robot cột sống. Đội ngũ ghép tạng xử lý ghép gan, thận, tim và tủy xương, và tập đoàn Apollo đã thực hiện hơn 43.000 ca ghép tạng.\n##technology\nBệnh viện có khoảng 550 giường và được JCI, NABH và NABL công nhận. Bệnh viện nằm tại Road No. 72, Film Nagar, Jubilee Hills.\n##international\nBệnh viện xử lý hơn 800 lượt tư vấn cho bệnh nhân quốc tế mỗi tháng, với bệnh nhân từ các nước bao gồm Hoa Kỳ, UAE, Tanzania, Kenya và Oman. Đội ngũ dịch vụ bệnh nhân quốc tế riêng hỗ trợ về visa y tế, sắp xếp du lịch, chỗ ở và phiên dịch.",
	'continental-hospitals':
		"##history\nContinental Hospitals được thành lập vào tháng 4 năm 2013 bởi bác sĩ Guru N. Reddy tại Financial District của Hyderabad (Nanakramguda, Gachibowli). Đây là bệnh viện 585 giường trải rộng trên 18 tầng và 1,4 triệu feet vuông, được JCI, NABH và NABL công nhận, là bệnh viện siêu chuyên khoa đầu tiên tại Ấn Độ đạt chứng nhận LEED, có phòng mổ xanh và NICU, PICU cấp 3. Bệnh viện giành giải ASSOCHAM Award 2022 cho Bệnh viện Tốt nhất Ấn Độ về Áp dụng Công nghệ.\n##specialities\nBệnh viện cung cấp hơn 50 chuyên khoa và nổi tiếng về ghép tạng phức tạp, khoa học tim mạch, thần kinh, ung bướu, khoa học dạ dày và chỉnh hình. Vào tháng 4 năm 2023, đội ngũ bác sĩ phẫu thuật do bác sĩ Pradeep Rachakonda dẫn dắt dưới sự hướng dẫn của bác sĩ Sudhir Srivastava đã thực hiện ca phẫu thuật bắc cầu mạch vành (CABG) hỗ trợ robot đầu tiên tại Ấn Độ với robot SSI Mantra. Khoa ghép tạng xử lý ghép gan, thận, tim, phổi và tủy xương, được hỗ trợ bởi ICU tiên tiến và phục hồi chức năng sau ghép.\n##technology\nBệnh viện có 16 phòng mổ xanh theo mô-đun và 90 giường ICU phòng riêng, với các bác sĩ phẫu thuật được đào tạo trên nền tảng da Vinci và các nền tảng robot khác.\n##international\nContinental có khu vực riêng cho bệnh nhân quốc tế và phòng chờ khám sức khỏe. Bệnh viện nằm tại Financial District, gần hành lang công nghệ thông tin Hyderabad, cách sân bay khoảng 30–45 phút.",
	'yashoda-hospitals-somajiguda':
		"##history\nYashoda Hospitals, Somajiguda, là bệnh viện đầu tiên của tập đoàn Yashoda, bắt đầu năm 1994, sau một phòng khám nhỏ do bác sĩ G. Surendar Rao mở năm 1989. Trong ba thập kỷ, tập đoàn đã mở rộng với các chi nhánh tại Somajiguda, Secunderabad, Malakpet và Hitec City. Đơn vị Somajiguda được AHPI công nhận là Bệnh viện Thân thiện với Bệnh nhân, và tập đoàn được Chính phủ Ấn Độ xếp hạng đầu về ghép tạng từ người hiến đã qua đời và đứng đầu trong số các bệnh viện đa chuyên khoa tại giải thưởng Times Healthcare Achievers.\n##specialities\nBệnh viện có hơn 400 giường, khoảng 250 bác sĩ và 500 y tá. Các trung tâm xuất sắc bao phủ phẫu thuật tim và lồng ngực, thần kinh, ung thư, ghép gan và ghép đa tạng, xương và khớp, thận học, khoa học robot, phẫu thuật cột sống, chăm sóc mẹ và bé cùng hiếm muộn, cùng danh sách rất rộng các khoa từ tai mũi họng và phụ khoa đến phẫu thuật thẩm mỹ, y học hạt nhân và phẫu thuật giảm béo. Các dấu mốc ghép tạng của tập đoàn bao gồm ca ghép phổi đầu tiên tại các bang nói tiếng Telugu (2012) và ca ghép tim-phổi kết hợp (2017).\n##technology\nPhòng xét nghiệm, dịch vụ chẩn đoán và nhà thuốc hoạt động suốt ngày đêm. Bệnh viện được NABH công nhận và là bệnh viện đầu tiên trong khu vực giới thiệu phẫu thuật robot.\n##international\nYashoda cung cấp dịch vụ cho bệnh nhân quốc tế, với chương trình ghép tạng xếp hạng trong số các chương trình đa tạng hàng đầu Ấn Độ, cùng đội ngũ đa chuyên khoa cho lọc máu, bệnh gan, thận và ghép tạng nhi khoa. Somajiguda nằm trên đường Raj Bhavan Road, trung tâm Hyderabad.",
	'global-hospitals-hyderabad':
		"##history\nGleneagles Global Hospitals tại Lakdi-ka-pul, được biết đến với tên Global Hospitals, là bệnh viện Gleneagles Global đầu tiên khai trương tại Hyderabad và thuộc Global Hospitals Group, thành lập năm 1999 bởi bác sĩ K. Ravindranath. Bệnh viện tiên phong ca ghép tim đầu tiên tại các bang cũ Andhra Pradesh và Telangana, thực hiện ca ghép tủy xương đầu tiên trong khu vực và ca ghép thận song sinh đầu tiên, cho biết ca ghép gan phân chia và ghép gan phụ trợ thành công đầu tiên tại Ấn Độ. Bệnh viện được xếp hạng là bệnh viện đa chuyên khoa tốt nhì Hyderabad và trong top 10 miền nam Ấn Độ theo khảo sát Times of India năm 2021.\n##specialities\nBệnh viện nổi tiếng về ghép gan, thận, tim và phổi, cũng cung cấp gan mật, thận học, giảm béo, tiêu hóa, ghép đa tạng, phẫu thuật thẩm mỹ và tạo hình, ung bướu, khoa học tim mạch, nhi khoa, tâm thần, nội tiết, tai mũi họng, chỉnh hình, phẫu thuật cột sống, khoa học dạ dày, phẫu thuật tổng quát và nội soi, cùng hô hấp.\n##technology\nBệnh viện có khoảng 150 giường và sáu phòng mổ, với khả năng robot và xâm lấn tối thiểu, cùng nhiều đơn vị ICU, bao gồm ICU phẫu thuật, ICU tim mạch, ICU chuyển tiếp, ICU gan và các đơn vị sau ghép. Bệnh viện được NABH và NABL công nhận.\n##international\nBệnh viện hỗ trợ bệnh nhân quốc tế thông qua tập đoàn Gleneagles Global. Lakdi-ka-pul là vị trí trung tâm Hyderabad, gần ga tàu điện ngầm Lakdi-ka-pul.",
	'kims-hospitals-secunderabad':
		"##history\nKIMS Hospitals, Secunderabad, khai trương năm 2004 với tư cách là bệnh viện chủ lực của tập đoàn Krishna Institute of Medical Sciences, bệnh viện chăm sóc chuyên sâu và cấp bốn 1.000 giường, một trong những bệnh viện tư nhân lớn nhất Ấn Độ. Tập đoàn được thành lập năm 2000 bởi bác sĩ phẫu thuật tim lồng ngực Bhaskar Rao Bollineni, người đã thực hiện hơn 30.000 ca phẫu thuật trong 25 năm và góp phần xây dựng chương trình Rajiv Gandhi Aarogyasri năm 2007. Tập đoàn hiện có hơn hai chục bệnh viện, và giám đốc điều hành kiêm CEO là bác sĩ Abhinay Bollineni.\n##specialities\nBệnh viện cung cấp hơn 25 chuyên khoa và siêu chuyên khoa, bao gồm tim mạch, tiêu hóa và gan mật, thần kinh, ghép tạng, ung bướu, chỉnh hình, tiết niệu, hiếm muộn, khoa học thận và chăm sóc mẹ và bé. Trung tâm thần kinh của bệnh viện xử lý u não, dị dạng cột sống, kích thích não sâu cho bệnh Parkinson và quản lý đột quỵ, và trung tâm KIMS Advanced Gastroenterology and Endoscopy (KAGE) điều trị các rối loạn tiêu hóa phức tạp, bệnh gan và các thủ thuật POEM.\n##technology\nChương trình ghép tạng bao phủ tim, phổi, gan, thận và tủy xương, bao gồm tưới máu ex vivo tiên tiến. Trung tâm ghép tim và phổi hoàn thành ca ghép tim đầu tiên năm 2012 và thực hiện khoảng 75 ca ghép tim và phổi mỗi năm, và bệnh viện ghi nhận 1.000 ca ghép thận năm 2019. Bệnh viện được NABH công nhận và có chứng nhận ISO 9001:2015.\n##international\nKIMS Secunderabad nằm trên đường Minister Road, trung tâm Secunderabad, gần ga đường sắt Secunderabad.",
};
